mapper.select:
SELECT
    COUNT(1)
FROM TB_TRMA_USER_INFO a
WHERE
    a.USER_ID = #{userId}
    AND a.USER_NM = #{userNm}

mapper.update:
UPDATE TB_TRMA_USER_INFO
SET USER_PW = #{userPw}
    ,UPDATE_USER = #{userId}
    ,UPDATE_DT = CURRENT_TIMESTAMP
WHERE USER_ID = #{userId}

mapper.select:
SELECT a.USER_NM ,a.AREA_NM ,a.DESCRIPTION ,a.AREA_NM_EN ,a.AREA_NM_JA ,a.DESCRIPTION_EN ,a.DESCRIPTION_JA ,a.PROFILE_IMG_URL ,COALESCE(f.RATING, 0) AS RATING ,COALESCE(b.MOIM_CNT, 0) AS MOIM_CNT ,COALESCE(c.MEMBER_CNT, 0) AS MOIM_MEMBER_CNT ,COALESCE(d.REVIRE_CNT, 0) AS MOIM_REVIRE_CNT ,a.LANG_CD ,e.CMM_CM_NM AS LANG_NM ,a.CREATE_DT AS JOIN_DT FROM TB_TRMA_USER_INFO a
LEFT JOIN ( SELECT CREATE_USER, COUNT(1) AS MOIM_CNT FROM TB_TRMA_MOIM_LIST WHERE CREATE_USER = #{userId} GROUP BY CREATE_USER ) b ON a.USER_ID = b.CREATE_USER LEFT JOIN ( SELECT c2.CREATE_USER ,COUNT(1) AS MEMBER_CNT FROM TB_TRMA_MOIM_MEMBER c1 LEFT JOIN TB_TRMA_MOIM_LIST c2 ON c1.MOIM_ID = c2.MOIM_ID WHERE c2.CREATE_USER = #{userId} GROUP BY c2.CREATE_USER ) c ON a.USER_ID = c.CREATE_USER
LEFT JOIN ( SELECT owner_id AS CREATE_USER, COUNT(1) AS REVIRE_CNT FROM ( SELECT d1.REVIEW_ID, d2.CREATE_USER AS owner_id FROM TB_TRMA_MOIM_REVIEW d1 LEFT JOIN TB_TRMA_MOIM_LIST d2 ON d1.MOIM_ID = d2.MOIM_ID WHERE d1.USE_YN = 'Y' AND d1.REVIEW_TYPE_CD = 'O' AND d2.CREATE_USER = #{userId} UNION SELECT d1.REVIEW_ID, d1.CREATE_USER AS owner_id FROM TB_TRMA_MOIM_REVIEW d1 WHERE d1.USE_YN = 'Y' AND d1.REVIEW_TYPE_CD = 'O' AND d1.CREATE_USER = #{userId} ) d_union GROUP BY owner_id ) d ON a.USER_ID = d.CREATE_USER LEFT JOIN ( SELECT owner_id AS CREATE_USER, AVG(REVIEW_SCORE) AS RATING FROM ( SELECT f1.REVIEW_ID, f1.REVIEW_SCORE, f2.CREATE_USER AS owner_id FROM TB_TRMA_MOIM_REVIEW f1 LEFT JOIN TB_TRMA_MOIM_LIST f2 ON f1.MOIM_ID = f2.MOIM_ID WHERE f1.REVIEW_TYPE_CD = 'O' AND f2.CREATE_USER = #{userId} UNION SELECT f1.REVIEW_ID, f1.REVIEW_SCORE, f1.CREATE_USER AS owner_id FROM TB_TRMA_MOIM_REVIEW f1 WHERE f1.REVIEW_TYPE_CD = 'O' AND f1.CREATE_USER = #{userId} ) f_union GROUP BY owner_id ) f ON a.USER_ID = f.CREATE_USER LEFT JOIN TB_TRMA_CMM_CD_D e ON a.LANG_CD = e.CMM_CDV AND e.CMM_CD_ID = 'LANG_CD' WHERE 1=1 AND a.USER_ID = #{userId}

mapper.update:
UPDATE TB_TRMA_USER_INFO
SET UPDATE_USER = #{userId}
    ,UPDATE_DT = CURRENT_TIMESTAMP

        ,USER_NM = #{request.userNm}


        ,AREA_NM = #{request.areaNm}
        ,AREA_NM_EN = NULL
        ,AREA_NM_JA = NULL


        ,DESCRIPTION = #{request.description}
        ,DESCRIPTION_EN = NULL
        ,DESCRIPTION_JA = NULL


        ,PROFILE_IMG_URL = #{request.profileImageUrl}

WHERE USER_ID = #{userId}

UPDATE TB_TRMA_USER_INFO
AREA_NM_EN = #{areaNmEn}, AREA_NM_JA = #{areaNmJa}, DESCRIPTION_EN = #{descriptionEn}, DESCRIPTION_JA = #{descriptionJa},
WHERE USER_ID = #{userId}
